    else
        result=$(curl -s -X "$http_method" "$url" -H "$TENANT_HEADER" -H "$CORRELATION_HEADER" -H "$AUTH_HEADER")
    fi

    if echo "$result" | grep -qE "$regex"; then
        echo -e "  ${GREEN}✅ PASSED${NC}"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC}"
        echo "  Regex not matched: $regex"
        echo "  Got: $(echo "$result" | head -c 300)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Regex '$regex' not matched")
        return 1
    fi
}

# Capture BOTH status code AND response body in a single request.
# Sets global variables: LAST_STATUS and LAST_BODY. Optional 4th arg = extra headers.
capture_with_status() {
    local http_method=$1
    local url=$2
    local payload=$3
    local extra_headers=$4
    local response

    local hdr_args=(-H "$TENANT_HEADER" -H "$CORRELATION_HEADER" -H "$AUTH_HEADER")
    if [ -n "$extra_headers" ]; then
        hdr_args+=(-H "$extra_headers")
    fi

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H 'Content-Type: application/json' "${hdr_args[@]}" -d "$payload")
    else
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" "${hdr_args[@]}")
    fi

    LAST_STATUS=$(echo "$response" | tail -1)
    LAST_BODY=$(echo "$response" | sed '$d')
}

# Assert status + capture body in one call (prevents double-POST problem).
# Optional 8th arg = extra headers.
assert_status_and_capture() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7
    local extra_headers=$8

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    capture_with_status "$http_method" "$url" "$payload" "$extra_headers"

    if [ "$LAST_STATUS" = "$expected_status" ]; then
        echo -e "  ${GREEN}✅ PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}❌ FAILED${NC} (Expected: $expected_status, Got: $LAST_STATUS)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $LAST_STATUS")
        return 1
    fi
}

