# Error: unknown reference code rejected on write -> 422.
assert_status 33 "Reject update with unknown currency_code (xref validation)" "BR-MS-PERS-002" \
    "PUT" "$BASE_URL/stores/$STORE_CODE" \
    "{\"name\":\"Acme Retail Group\",\"phone\":\"+1-514-555-0100\",\"email\":\"ops@acme.example\",\"city\":\"Montreal\",\"postal_code\":\"H2X1Y4\",\"country_iso\":\"CA\",\"zone_code\":\"QC\",\"default_language_code\":\"en\",\"currency_code\":\"ZZZ\",\"language_codes\":[\"en\"]}" \
    "422"

# --- BR-MS-PERS-003: a store code resolves to exactly one store ---
# Success: lookup by code returns the single matching store.
assert_json_field 34 "Lookup by code returns the single matching store" "BR-MS-PERS-003" \
    "GET" "$BASE_URL/stores/$STORE_CODE" \
    "null" \
    "\"code\":\"$STORE_CODE\""

# Error: lookup of a nonexistent code -> 404.
assert_status 35 "Lookup of nonexistent code returns 404" "BR-MS-PERS-003" \
    "GET" "$BASE_URL/stores/nonexistent_$SFX" \
    "null" \
    "404"

# ============================================
# SECTION 5: BR-MS-LIFE — Store lifecycle & state machine (4 rules)
# ============================================
echo ""
echo -e "${CYAN}══════════════════════════════════════════════════${NC}"
echo -e "${CYAN}SECTION 5: BR-MS-LIFE — Store lifecycle (4 rules)${NC}"
echo -e "${CYAN}══════════════════════════════════════════════════${NC}"

# --- BR-MS-LIFE-001: creating a store sends a new-store notification ---
# Behavioral: a create (Transient -> Active) succeeds; edit path emits no notification.
LIFE_CODE="newshop_$SFX"
assert_status_and_capture 36 "Create store (Transient -> Active) triggers store.created" "BR-MS-LIFE-001" \
    "POST" "$BASE_URL/stores" \
    "{\"code\":\"$LIFE_CODE\",\"name\":\"New Shop\",\"phone\":\"+1-514-555-0109\",\"email\":\"owner@newshop.example\",\"city\":\"Montreal\",\"postal_code\":\"H2X1Y4\",\"country_iso\":\"CA\",\"zone_code\":\"QC\",\"default_language_code\":\"en\",\"currency_code\":\"CAD\",\"language_codes\":[\"en\"]}" \
    "201"

# Behavioral (state transition): the newly created store is Active — retrievable by code.
assert_status 37 "Newly created store is Active (retrievable)" "BR-MS-LIFE-001" \
    "GET" "$BASE_URL/stores/$LIFE_CODE" \
    "null" \
    "200"

# Edit of an existing store emits no notification (still a successful 200 update).
assert_status 38 "Edit of existing store emits no new-store notification" "BR-MS-LIFE-001" \
    "PUT" "$BASE_URL/stores/$LIFE_CODE" \
    "{\"name\":\"New Shop Renamed\",\"phone\":\"+1-514-555-0109\",\"email\":\"owner@newshop.example\",\"city\":\"Montreal\",\"postal_code\":\"H2X1Y4\",\"country_iso\":\"CA\",\"zone_code\":\"QC\",\"default_language_code\":\"en\",\"currency_code\":\"CAD\",\"language_codes\":[\"en\"]}" \
    "200"

# --- BR-MS-LIFE-003: only a superadmin may delete a store (auth gate before saga) ---
# Error: a plain store-admin decommission attempt is refused -> 403 (state unchanged).
assert_status 39 "Store-admin decommission is refused (superadmin required)" "BR-MS-LIFE-003" \
    "DELETE" "$BASE_URL/stores/$LIFE_CODE" \
    "null" \
    "403" \
    "$STOREADMIN_HEADER"

# State-machine: after the refused delete, the store is still Active (unchanged).
assert_status 40 "Store remains Active after refused decommission" "BR-MS-LIFE-003" \
    "GET" "$BASE_URL/stores/$LIFE_CODE" \
    "null" \
    "200"

# --- BR-MS-LIFE-002: deleting a store decommissions its tenant data (saga) ---
# Behavioral (Active -> Decommissioning): superadmin decommission accepted -> 202.
assert_status_and_capture 41 "Superadmin decommission starts merchant.deleted saga" "BR-MS-LIFE-002" \
    "DELETE" "$BASE_URL/stores/$LIFE_CODE" \
    "null" \
    "202" \
    "$SUPERADMIN_HEADER"

# Response-shape fidelity: DecommissionResponse carries the Decommissioning status.
# Uses a distinct store (complete_$SFX) so the decommission body is fresh; assert_json_field
# sends the required Authorization header (superadmin token substituted via AUTH_HEADER below is
# not available in assert_json_field, so this test targets the response shape of an accepted saga).
capture_with_status "DELETE" "$BASE_URL/stores/complete_$SFX" "null" "$SUPERADMIN_HEADER"
TOTAL=$((TOTAL + 1))
echo -e "\n${BLUE}Test 42: Decommission response reports Decommissioning status${NC}"
echo -e "  Rule: BR-MS-LIFE-002 | Expected pattern: \"status\":\"Decommissioning\""
if echo "$LAST_BODY" | grep -q '"status":"Decommissioning"'; then
    echo -e "  ${GREEN}✅ PASSED${NC}"
    PASSED=$((PASSED + 1))
else
    echo -e "  ${RED}❌ FAILED${NC}"
    echo "  Got: $(echo "$LAST_BODY" | head -c 300)"
    FAILED=$((FAILED + 1))
    FAILED_TESTS+=("Test 42: Decommission response status [BR-MS-LIFE-002] - pattern not found")
fi

# State-machine: the reserved DEFAULT store cannot be decommissioned -> 409 (illegal transition).
assert_status 43 "Reserved DEFAULT store cannot be decommissioned" "BR-MS-LIFE-002" \
    "DELETE" "$BASE_URL/stores/DEFAULT" \
    "null" \
    "409" \
    "$SUPERADMIN_HEADER"

# --- BR-MS-LIFE-004: a store-admin may only edit the store they are bound to ---
# Success: create a second store to represent a different tenant scope.
assert_status 44 "Create a second store (different tenant scope)" "BR-MS-LIFE-004" \
    "POST" "$BASE_URL/stores" \
    "{\"code\":\"$SECOND_CODE\",\"name\":\"Rival\",\"phone\":\"+1-514-555-0110\",\"email\":\"rival@acme.example\",\"city\":\"Montreal\",\"postal_code\":\"H2X1Y4\",\"country_iso\":\"CA\",\"zone_code\":\"QC\",\"default_language_code\":\"en\",\"currency_code\":\"CAD\",\"language_codes\":[\"en\"]}" \
    "201"

# Error: editing a store outside the caller's bound scope is refused -> 403 (nothing changed).
assert_status 45 "Cross-store edit is refused (own-store only)" "BR-MS-LIFE-004" \
    "PUT" "$BASE_URL/stores/$SECOND_CODE" \
    "{\"name\":\"Sabotage\",\"phone\":\"+1-514-555-0110\",\"email\":\"rival@acme.example\",\"city\":\"Montreal\",\"postal_code\":\"H2X1Y4\",\"country_iso\":\"CA\",\"zone_code\":\"QC\",\"default_language_code\":\"en\",\"currency_code\":\"CAD\",\"language_codes\":[\"en\"]}" \
    "403" \
    "x-tenant-id: other-tenant-999"

